int change_font_data(const unsigned char *data, uint8_t w, uint8_t h) {
    if (!data || w != 8 || h == 0 || h > 32) return -EINVAL;
    uint64_t font_size = 256ULL * h;
    if (current_font_w == w && current_font_h == h && memcmp(current_font, data, font_size) == 0) return 0;
    memcpy(current_font, data, font_size);
    current_font_w = w;
    current_font_h = h;
    current_font_generation++;
    sync_terminal();
    return 0;
}

int change_font(const char *path, uint8_t w, uint8_t h) {
    if (!path) return -EINVAL;
    if (!w || !h) return -EINVAL; // Sanity check if width or height is 0

    char abs_path[256];
    build_vfs_path(path, abs_path, sizeof(abs_path));

    void *font_data = NULL;
    uint64_t font_size = 0;
    int r = load_vfs(abs_path, &font_data, &font_size, sizeof(current_font));
    if (r < 0) return r;

    if (!font_data || font_size == 0 || font_size > sizeof(current_font)) {
        free(font_data);
        return -ENOENT;
    }
    if ((uint64_t)256 * h * w / 8 != font_size) {
        free(font_data);
        return -EFBIG;
    }
    r = change_font_data(font_data, w, h);
    free(font_data);
    return r;
}

void init_default_font(void) {
    if (!fb_req.response || fb_req.response->framebuffer_count < 1) return;
    struct limine_framebuffer *fb = fb_req.response->framebuffers[0];
    if (fb->width % 8 == 0 && fb->height % 16 == 0) {
        memcpy(current_font, builtin_8x16_font, sizeof(builtin_8x16_font));
        current_font_w = 8;
        current_font_h = 16;
    } else if (fb->width % 8 == 0 && fb->height % 15 == 0) {
        memcpy(current_font, builtin_8x15_font, sizeof(builtin_8x15_font));
        current_font_w = 8;
        current_font_h = 15;
    } else {
        // We can't print the output without the font, so just silently halt
        halt();
    }
    current_font_generation++;
    log("fonts: initialized %dx%d font\n", current_font_w, current_font_h); // Now we can use functions like log() again!
}
